/****************************************************************************
 * Name: esp32s3_cam_start_xclk
 *
 * Description:
 *   Generate 20MHz XCLK for OV2640 using LEDC peripheral.
 *   Uses 80MHz APB clock, 1-bit resolution (2 levels), div=2 -> 20MHz.
 *   50% duty cycle: high=1, low=1.
 *
 ****************************************************************************/

static void esp32s3_cam_start_xclk(void)
{
  uint32_t timer_sel = CAM_LEDC_TIMER;
  uint32_t chan_sel = CAM_LEDC_CHANNEL;

  /* Enable LEDC peripheral clock */

  periph_module_enable(PERIPH_LEDC_MODULE);

  /* Configure LEDC timer:
   * - clock source: APB_CLK (80 MHz)
   * - divisor: 2 -> tick rate = 40 MHz
   * - duty resolution: 1 bit -> freq = 40 / 2 = 20 MHz
   */

  putreg32((1 << LEDC_TIMER0_CONF_TICK_SEL_S) |   /* APB_CLK */
           (2 << LEDC_TIMER0_CONF_DIVIDER_S) |     /* div = 2 */
           (0 << LEDC_TIMER0_CONF_DUTY_RES_S),      /* 1-bit */
           LEDC_TIMER0_CONF_REG);

  /* Timer resume */

  putreg32(1 << LEDC_TIMER0_CONF_PARA_UP_S,
           LEDC_TIMER0_CONF_REG);

  /* Configure LEDC channel:
   * - timer select: timer 0
   * - duty: 1 (50% of 2^1 = 2)
   * - output GPIO: XCLK pin
   */

  putreg32((timer_sel << LEDC_CH0_CONF0_TIMER_SEL_S),
           LEDC_CH0_CONF0_REG);

  /* Set duty: 1 out of 2 (50%) */

  putreg32(1 << LEDC_CH0_DUTY_DUTY_S,
           LEDC_CH0_DUTY_REG);

  /* Update duty */

  putreg32(1 << LEDC_CH0_CONF1_PARA_UP_S,
           LEDC_CH0_CONF1_REG);

  /* Connect LEDC channel output to XCLK pin via GPIO matrix */

  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_XCLK, OUTPUT);
  esp32s3_gpio_matrix_out(ESP32S3_DAMI_CAM_PIN_XCLK,
                           LEDC_LS_SIG_OUT0_IDX + chan_sel, 0, 0);

  /* Start timer */

  putreg32((2 << LEDC_TIMER0_CONF_TICK_SEL_S) |
           (2 << LEDC_TIMER0_CONF_DIVIDER_S) |
           (0 << LEDC_TIMER0_CONF_DUTY_RES_S) |
           (1 << LEDC_TIMER0_CONF_PARA_UP_S),
           LEDC_TIMER0_CONF_REG);

  syslog(LOG_INFO, "cam: XCLK started at %d Hz\n", CAM_XCLK_FREQ_HZ);
}

