#include <nuttx/config.h>

#include <stdio.h>
#include <errno.h>

#include <nuttx/i2c/i2c_master.h>
#include <nuttx/video/ov2640.h>
#include <nuttx/video/v4l2_cap.h>

#include "esp32s3_cam.h"
#include "esp32s3_i2c.h"

#include "esp32dami.h"

int board_camera_initialize(void)
{
  FAR struct i2c_master_s *i2c;
  int ret;

  printf("board_camera: start init\n");

  /* Init camera data interface FIRST - this generates XCLK for OV2640 */

  ret = esp32s3_cam_initialize();
  if (ret < 0)
    {
      printf("board_camera: cam init failed: %d\n", ret);
      return ret;
    }

  printf("board_camera: XCLK running, init I2C\n");

  /* Now init I2C - OV2640 needs XCLK to respond */

  i2c = esp32s3_i2cbus_initialize(0);
  if (i2c == NULL)
    {
      printf("board_camera: I2C init failed\n");
      return -ENODEV;
    }

  printf("board_camera: I2C ok, init OV2640\n");

  ret = ov2640_initialize(i2c);
  if (ret < 0)
    {
      printf("board_camera: ov2640 failed: %d\n", ret);
      return ret;
    }

  printf("board_camera: registering /dev/video\n");

  ret = capture_register("/dev/video", NULL, NULL, 0);
  if (ret < 0)
    {
      printf("board_camera: capture_register failed: %d\n", ret);
      return ret;
    }

  printf("board_camera: done!\n");
  return OK;
}

