/****************************************************************************
 * Name: esp32s3_cam_start_xclk
 *
 * Description:
 *   Generate 20MHz XCLK for OV2640 using LEDC peripheral.
 *
 *   LEDC timer formula: freq = clk_src / (clk_div * 2^duty_res)
 *   Using APB_CLK = 80 MHz, duty_res = 1 (2 levels), clk_div = 2:
 *     freq = 80 / (2 * 2) = 20 MHz
 *
 *   CLK_DIV_TIMER0 is a 18-bit fixed-point: 8-bit integer + 8-bit fraction.
 *   div = 2.0 → integer_part = 2, fractional_part = 0 → (2 << 8) = 0x200
 *
 *   HPOINT = 0, DUTY = 1 → 50% duty cycle (high for 1 tick, low for 1 tick)
 *
 ****************************************************************************/

static void esp32s3_cam_start_xclk(void)
{
  uint32_t timer_reg;
  uint32_t chan_conf0;

  /* Enable LEDC peripheral clock */

  periph_module_enable(PERIPH_LEDC_MODULE);

  /* Configure LEDC timer 0:
   * - CLK_DIV = 2.0 (integer=2, frac=0) → (2 << 8) = 0x200
   * - DUTY_RES = 1 (1-bit, 2 levels)
   * - TICK_SEL = 1 (use REF_TICK / APB_CLK)
   * - PARA_UP = 1 (apply settings)
   */

  timer_reg = (0x200 << LEDC_CLK_DIV_TIMER0_S) |    /* div = 2.0 */
              (1 << LEDC_TIMER0_DUTY_RES_S) |        /* 1-bit resolution */
              (1 << LEDC_TICK_SEL_TIMER0_S) |         /* APB_CLK */
              (1 << LEDC_TIMER0_PARA_UP_S);            /* update */

  putreg32(timer_reg, LEDC_TIMER0_CONF_REG);

  /* Configure LEDC channel 0:
   * - TIMER_SEL = 0 (use timer 0)
   * - SIG_OUT_EN = 1 (enable output)
   * - HPOINT = 0 (high starts at tick 0)
   * - DUTY = 1 (high for 1 out of 2 ticks = 50%)
   * - DUTY_START = 1 (enable duty cycle)
   * - PARA_UP = 1 (apply settings)
   */

  chan_conf0 = (CAM_LEDC_TIMER << LEDC_TIMER_SEL_CH0_S) |
               (1 << LEDC_SIG_OUT_EN_CH0_S);

  putreg32(chan_conf0, LEDC_CH0_CONF0_REG);

  /* Set HPOINT = 0, DUTY = 1 */

  putreg32((0 << LEDC_HPOINT_CH0_S) |
           (1 << LEDC_DUTY_CH0_S),
           LEDC_CH0_DUTY_REG);

  /* Trigger parameter update */

  putreg32(1 << LEDC_PARA_UP_CH0_S, LEDC_CH0_CONF0_REG);

  /* Connect LEDC channel 0 output to XCLK pin via GPIO matrix */

  esp32s3_configgpio(ESP32S3_DAMI_CAM_PIN_XCLK, OUTPUT);
  esp32s3_gpio_matrix_out(ESP32S3_DAMI_CAM_PIN_XCLK,
                           LEDC_LS_SIG_OUT0_IDX + CAM_LEDC_CHANNEL,
                           0, 0);

  syslog(LOG_INFO, "cam: XCLK started (20MHz)\n");
}

